Translate the TypeScript below into Jac. Output only a ```jac``` code block containing the translation.
```ts
export interface Post {
  title: string
  date: string
  draft: boolean
  fields: {
    slug: string
  }
  excerpt: string
  code: {
    scope: string
    body: string
  }
}

export interface PostUnnormalized {
  frontmatter: {
    title: string
    date: string
    draft: boolean
  }
  fields: {
    slug: string
  }
  excerpt: string
  code: {
    scope: string
    body: string
  }
}

export interface YearPort {
  year: number
  posts: Post[]
}

export function normalizePost(post: PostUnnormalized) {
  return {
    ...post,
    ...post.frontmatter,
  }
}

export function sortPostsBySameYear(posts: Post[] = []): YearPort[] {
  return posts
    .sort((a, b) => {
      const compare = new Date(b.date).getTime() - new Date(a.date).getTime()
      return compare
    }) 
    .reduce((prev: YearPort[], post: Post) => {
      const year: number = new Date(post.date).getFullYear()
      const yearPosts = prev.find(p => p.year === year)
      !yearPosts
        ? prev.push({ year, posts: [post] })
        : yearPosts.posts.push(post)

      return prev
    }, [])
}
```

```jac
def:pub normalizePost(post: dict) -> dict {
    return {**post, **post["frontmatter"]};
}

def post_date_key(p: dict) -> str {
    return str(p["date"]);
}

def:pub sortPostsBySameYear(posts: list[dict] = []) -> list[dict] {
    sorted_posts = sorted(posts, key=post_date_key, reverse=True);
    result: list[dict] = [];
    for post in sorted_posts {
        year = int(str(post["date"])[:4]);
        matched = False;
        for entry in result {
            if entry["year"] == year {
                entry["posts"] = entry["posts"] + [post];
                matched = True;
                break;
            }
        }
        if not matched {
            result = result + [{"year": year, "posts": [post]}];
        }
    }
    return result;
}
