import from "@material-ui/core" { Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle }

def:pub ConfirmBranch(
    isOpen: bool,
    description: str,
    disagreeText: str,
    agreeText: str,
    hasCloseButton: bool,
    onClose: Callable[[], None],
    onConfirm: Callable[[], None],
    title: str | None = None,
) -> JsxElement {
    <Dialog
        open={isOpen}
        onClose={onClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
    >
        {title and <DialogTitle id="alert-dialog-title">{title}</DialogTitle>}
        <DialogContent>
            <DialogContentText id="alert-dialog-description">{description}</DialogContentText>
        </DialogContent>
        <DialogActions>
            {hasCloseButton and <Button onClick={onClose} color="primary">{disagreeText}</Button>}
            <Button onClick={onConfirm} color="primary" variant="contained" autoFocus>{agreeText}</Button>
        </DialogActions>
    </Dialog>
}
