    has value: int = 0;
    tabs_data = data or [];

    can with entry {
        hash = window.location.hash.replace("#/", "");
        value = 0;
        if tabs_data {
            for (index, item) in enumerate(tabs_data) {
                if item.get("id") == hash {
                    value = index;
                }
            }
        }
    }

