        <AppBar position="static" color="default">
            <MaterialTabs
                value={value}
                onChange={handle_change}
                indicatorColor="primary"
                textColor="primary"
                variant={"scrollable" if isScrollable else "standard"}
            >
                {for item in tabs_data {
                    <Tab key={str(item.get("id", ""))} label={str(item.get("label", ""))} />
