	value: string;
	onValueChange: (value: string) => void;
	onSubmit: (options: SendOptions) => void;
	formLabel: string;
	inputLabel: string;
	placeholder: string;
	rows?: number;
	autoFocus?: boolean;
	hint: string;
	header?: ReactNode;
