  variant?: keyof typeof variants;
  buttonSize?: keyof typeof sizes;
  disabled?: boolean;
  children: ReactNode;
} & SystemProps;

type ButtonProps =
  | ({ as?: never } & ButtonType & CustomProps)
  | ({ as: 'a' } & AnchorType & CustomProps);

