          as={_defaultElement}
          {...props}
          ref={ref}
          position="relative"
          data-is-loading
          aria-disabled
          disabled
        >
          <Box
            position="absolute"
            top="50%"
            left="50%"
            transform="translate(-50%, -50%)"
          >
            <Spinner />
          </Box>
          <Box display="flex" color="transparent">
            {props?.children}
          </Box>
        </StyledButton>
      );
    }

    if (to) {
      return (
        <Link href={to} passHref>
          {/* @ts-expect-error */}
          <StyledButton as="a" {...props} ref={ref} />
        </Link>
      );
    }

    // @ts-expect-error
    return <StyledButton as={_defaultElement} {...props} ref={ref} />;
  },
);

(Button as StyledConfigType).config = {
  variant: variants,
  buttonSize: sizes,
};
