def:pub shallowCompare(a: object, b: object) -> bool {
    if a is b {
        return True;
    }
    if isinstance(a, list) and isinstance(b, list) {
        return all(b[i] == e for (i, e) in enumerate(a));
    }
    if isinstance(a, dict) and isinstance(b, dict) {
        keys = list(set(list(a.keys()) + list(b.keys())));
        return all(a[key] == b[key] for key in keys);
    }
    return False;
}

def:pub pascalCase(s: str) -> str {
    return f"{s[0].upper()}{s[1:]}";
}

def:pub pruneKeys(record: dict[str, object], *key_groups: list) -> dict[str, object] {
    keys_to_remove = set();
    for group in key_groups {
        for key in group {
            keys_to_remove.add(key);
        }
    }
    return {k: v for (k, v) in record.items() if k not in keys_to_remove};
}
