def _pad(n: int) -> str {
    return str(n).zfill(2);
}

def toLocalInputValue(iso: str) -> str {
    date = parseISO(iso);
    yyyy = date.getFullYear();
    mm = _pad(date.getMonth() + 1);
    dd = _pad(date.getDate());
    hh = _pad(date.getHours());
    min = _pad(date.getMinutes());
    return f"{yyyy}-{mm}-{dd}T{hh}:{min}";
}

def fromLocalInputValue(value: str) -> object | None {
    if (not value) {
        return None;
    }
    date = Date(value);
    if (isNaN(date.getTime())) {
        return None;
    }
    return date;
}

def ensureValidTimeRange(start: object, end: object) -> dict[str, object] {
    if (end <= start) {
        return {"start": start, "end": addMinutes(start, 30)};
    }
