glob DELAY = 2000;
glob timerId: float | None = None;

def:pub useController(params: dict[str, object]) -> dict[str, object] {
    isVisible = params["isVisible"] as bool;
    has show: bool = False;

    import from "react" { useEffect, useRef }
    showRef = useRef(False);

    useEffect(lambda {
        if timerId is not None {
            clearTimeout(timerId);
        }
        if isVisible {
            showRef.current = True;
            show = True;
        } else {
            timerId = setTimeout(lambda { show = False; }, DELAY) as float;
        }
        return lambda {
            if timerId is not None {
                clearTimeout(timerId);
            }
        };
    }, [isVisible]);

    return {"show": show};
}
