  selected?: boolean;
  tracked?: boolean;
  expanded?: boolean;
  labelText?: string;
  labelIcon?: SvgIconComponent;
  expandIcon?: SvgIconComponent;
  toggleExpanded?: () => void;
  children?: React.ReactNode;
};

