import json;
import from datetime { datetime }

glob TRUNCATE_LIMIT = 15;

def timestamp() -> str {
    d = datetime.now();
    ms = d.microsecond // 1000;
    return f"{d.hour:02d}:{d.minute:02d}:{d.second:02d}.{ms:03d}";
}

def:pub truncateStr(value: str, limit: int = TRUNCATE_LIMIT) -> str {
    if (len(value) > limit) {
        return value[0:limit] + "…";
    }
    return value;
}

def truncateDeep(value: object | str | float | bool | list[object] | None, limit: int) -> object | str | float | bool | list[object] | None {
    if (value is None) {
        return value;
    }
    if isinstance(value, str) {
        return truncateStr(value, limit);
    }
    if isinstance(value, (int, float, bool)) {
        return value;
    }
    if isinstance(value, list) {
        return [truncateDeep(item, limit) for item in value];
    }
    if isinstance(value, dict) {
        result: dict[str, object] = {};
        for key in value {
            result[key] = truncateDeep(value[key], limit);
        }
        return result;
    }
    return value;
}

def:pub summarizeValue(value: object | str | float | bool | list[object] | None, limit: int = TRUNCATE_LIMIT) -> str {
    if (value is None) {
        return "undefined";
    }
    try {
        return json.dumps(truncateDeep(value, limit));
    } except Exception {
        return str(value);
    }
}
