```jac
import from "@/data/agent-skills" { agentSkillsData }
import from "@/lib/site-url" { resolveSiteBaseUrl }

glob:pub dynamic = "force-static";

def:pub sitemap() -> list[dict[str, object]] {
    baseUrl = resolveSiteBaseUrl();
    staticRoutes = [];
    for route in ["/", "/about", "/projects", "/agent-skills", "/contact"] {
        url = str(URL(route, baseUrl));
        priority = 1.0 if route == "/" else 0.8;
        staticRoutes = staticRoutes + [{"url": url, "changeFrequency": "monthly", "priority": priority}];
    }
    agentSkillRoutes = [];
    for skill in agentSkillsData {
        detailHref = skill["detailHref"] as str;
        featured = skill["featured"] as bool;
        agentSkillRoutes = agentSkillRoutes + [{"url": str(URL(detailHref, baseUrl)), "changeFrequency": "weekly", "priority": 0.7 if featured else 0.6}];
    }
    return staticRoutes + agentSkillRoutes;
}
