import from "classnames" { default as classNames }
import from "react" { Children, cloneElement }

glob sizeStyle = {"default": "h-5 w-5 text-xs", "small": "h-4 w-4 text-xs"};

def computedCount(count: int, minNum: int, overflowCount: int) -> str | int {
    if count and count > minNum {
        if overflowCount {
            if count > overflowCount {
                return str(overflowCount) + "+";
            }
            return count;
        }
        return count;
    }
    return "";
}

def countStyle(size: str, countVal: str | int) -> dict[str, object] {
    length: int = len(str(countVal));
    if length == 1 {
        return {"borderRadius": "50%"};
    }
    if size == "default" {
        return {"width": str(length * 0.5 + 0.75) + "rem", "borderRadius": "20px"};
    }
    return {"width": str(length * 0.4 + 0.75) + "rem", "borderRadius": "20px"};
}

def countRight(size: str, countVal: str | int, offset: list[int] | None) -> float {
    length: int = len(str(countVal));
    if length == 1 {
        if offset {
            return (-offset[0] - 10) if size == "default" else (-offset[0] - 8);
        }
        return -10.0 if size == "default" else -8.0;
    }
    if offset {
        return (-offset[0] - (length * 0.5 + 0.75) * 8) if size == "default" else (-offset[0] - (length * 0.4 + 0.75) * 8);
    }
    return (-(length * 0.5 + 0.75) * 8) if size == "default" else (-(length * 0.4 + 0.75) * 8);
}

def countTop(size: str, offset: list[int] | None) -> float {
    if offset {
        return (-offset[1] - 10) if size == "default" else (-offset[1] - 8);
    }
    return -10.0 if size == "default" else -6.0;
}

def:pub Badge(
    color: str = "",
    count: int = 0,
    offset: list[int] | None = None,
    overflowCount: int = 0,
    showZero: bool = False,
    size: str = "default",
    title: str = "",
    className: str = "",
    style: dict[str, object] | None = None,
    children: object | None = None,
) -> JsxElement {
    resolvedStyle: dict[str, object] = style if style else {};
    resolvedSize: str = size if count else "default";
    minNum: int = -1 if showZero else 0;
    countVal: str | int = computedCount(count, minNum, overflowCount);
    badgeStyle: dict[str, object] = {
        "right": countRight(resolvedSize, countVal, offset),
        "top": countTop(resolvedSize, offset),
        "backgroundColor": color,
        **countStyle(resolvedSize, countVal),
    };
    overlay = <div
        className={classNames(
            "absolute box-border flex items-center justify-center border text-white transition focus:outline-none",
            sizeStyle[resolvedSize],
            className,
        )}
        style={badgeStyle}
        title={title}
    >{countVal}</div>;
    if children {
        return Children.map(children, lambda (c: object) {
            return cloneElement(
                c,
                {"className": "relative"},
                <div style={resolvedStyle}>{overlay}</div>,
            );
        });
    }
    <div style={resolvedStyle}>
        <div
            className={classNames(
                "box-border flex items-center justify-center border text-white transition focus:outline-none",
                sizeStyle[resolvedSize],
                className,
            )}
            style={badgeStyle}
            title={title}
        >{countVal}</div>
    </div>
}
