import from "remark-mdx-code-meta" { default as remarkMdxCodeMeta }

def:pub patchWebpackConfig(config: dict[str, object]) -> dict[str, object] {
    mdxExt = ".mdx";
    mdx2Loader = "@storybook/mdx2-csf";
    rules = config["module"]["rules"] as list[dict[str, object]];
    mdxRules = [rule for rule in rules if rule.get("test") and mdxExt in str(rule["test"])];
    for rule in mdxRules {
        use = rule.get("use") as list[dict[str, object]];
        if use and len(use) > 0 {
            loader = use[0].get("loader", "") as str;
            if mdx2Loader in loader {
                options = use[0]["options"] as dict[str, object];
                compile_opts = options["mdxCompileOptions"] as dict[str, object];
                plugins = compile_opts["remarkPlugins"] as list[object];
                compile_opts["remarkPlugins"] = plugins + [remarkMdxCodeMeta];
            }
        }
    }
    return config;
}
