            try {
                fetched = await func();
                setStatus("succeed");
                setResult(fetched);
            } except Exception as caught {
                setStatus("failed");
                setError(caught);
            }
        }
        invokeFunction();
    }, []);
    return OptimisticUIState[T](status=status, result=result, error=error);
}
