```ts
import type { ResumeConfig } from '@/components/types';
import type { ResumeModuleKey } from '@/config/types';
import type { AIImproveTarget } from '@/services/ai/types';

const AI_ENABLED_FIELDS: Partial<Record<ResumeModuleKey, string[]>> = {
  aboutme: ['aboutme_desc'],
  projectList: ['project_content', 'project_desc'],
  workExpList: ['work_desc'],
};

export const isAIImprovementSupported = (
  moduleKey: ResumeModuleKey,
  fieldKey: string
): boolean => {
  return AI_ENABLED_FIELDS[moduleKey]?.includes(fieldKey) ?? false;
};

export const applyAIFieldResult = (
  config: ResumeConfig,
  target: AIImproveTarget
): ResumeConfig => {
  const { moduleKey, fieldKey, itemIndex, value = '' } = target;

  if (!isAIImprovementSupported(moduleKey, fieldKey)) {
    return config;
  }

  if (moduleKey === 'aboutme') {
    return {
      ...config,
      aboutme: {
        ...(config.aboutme || { aboutme_desc: '' }),
        [fieldKey]: value,
      },
    };
  }

  if (moduleKey === 'workExpList' || moduleKey === 'projectList') {
    if (typeof itemIndex !== 'number') {
      return config;
    }

    const list = [...(config[moduleKey] || [])];
    const currentItem = list[itemIndex];

    if (!currentItem) {
      return config;
    }

    list[itemIndex] = {
      ...currentItem,
      [fieldKey]: value,
    };

    return {
      ...config,
      [moduleKey]: list,
    };
  }

  return config;
};
```

```jac
glob AI_ENABLED_FIELDS: dict[str, list[str]] = {
    "aboutme": ["aboutme_desc"],
    "projectList": ["project_content", "project_desc"],
    "workExpList": ["work_desc"],
};

def:pub isAIImprovementSupported(moduleKey: str, fieldKey: str) -> bool {
    fields = AI_ENABLED_FIELDS.get(moduleKey);
    return fields is not None and fieldKey in fields;
}

def:pub applyAIFieldResult(config: dict[str, object], target: dict[str, object]) -> dict[str, object] {
    moduleKey = target["moduleKey"] as str;
    fieldKey = target["fieldKey"] as str;
    itemIndex = target.get("itemIndex");
    value = target.get("value", "");
    if not isAIImprovementSupported(moduleKey, fieldKey) {
        return config;
    }
    if moduleKey == "aboutme" {
        aboutme = config.get("aboutme") as dict[str, object] | None;
        base = aboutme if aboutme else {"aboutme_desc": ""};
        return {**config, "aboutme": {**base, fieldKey: value}};
    }
    if moduleKey == "workExpList" or moduleKey == "projectList" {
        if not isinstance(itemIndex, int) {
            return config;
        }
        entries = (config.get(moduleKey) as list[dict[str, object]] | None) or [];
        if itemIndex < 0 or itemIndex >= len(entries) {
            return config;
        }
        currentItem = entries[itemIndex];
        entries = entries[:itemIndex] + [{**currentItem, fieldKey: value}] + entries[itemIndex + 1:];
        return {**config, moduleKey: entries};
    }
    return config;
